class AgentState(FrozenModel):
    mode: AgentMode = AgentMode.PAUSED
    version: int = 0
    execution_epoch: str = "not-started"
    reconciled_epoch: str | None = None
    active_order_ids: tuple[str, ...] = ()
    equity_peak: Decimal | None = None
    reason: str = "initialized safely in PAUSED"
    updated_at: datetime = Field(default_factory=lambda: datetime.now(UTC))

    @model_validator(mode="before")
    @classmethod
    def adopt_legacy_active_order(cls, data: Any) -> Any:
        """Reads durable state written before concurrent positions were allowed."""
        if not isinstance(data, dict) or "active_order_id" not in data:
            return data
        migrated = dict(data)
        legacy = migrated.pop("active_order_id")
        if legacy is not None and not migrated.get("active_order_ids"):
            migrated["active_order_ids"] = (legacy,)
        return migrated

    @model_validator(mode="after")
    def validate_active_order_ids(self) -> AgentState:
        if len(set(self.active_order_ids)) != len(self.active_order_ids):
            raise ValueError("active order ids must be unique")
        return self

    @property
    def is_reconciled(self) -> bool:
        return self.execution_epoch == self.reconciled_epoch

def claim_order(
    self, execution: OrderExecution, *, expected_epoch: str, max_active_orders: int
) -> bool: ...

def close_position(self, symbol: str) -> None:
    """Cancels the symbol's resting bracket legs, then closes just that position."""
    orders = cast(
        list[Order],
        self._client.get_orders(
            filter=GetOrdersRequest(
                status=QueryOrderStatus.OPEN, symbols=[symbol], limit=500
            )
        ),
    )
    for order in orders:
        try:
            self._client.cancel_order_by_id(str(order.id))
        except APIError as exc:
            if exc.status_code not in {404, 422}:
                raise
    try:
        self._client.close_position(symbol)
    except APIError as exc:
        if exc.status_code != 404:
            raise

def flatten(self) -> None:
    self._client.close_all_positions(cancel_orders=True)

def claim_order(
    self, execution: OrderExecution, *, expected_epoch: str, max_active_orders: int
) -> bool:
    with self._lock:
        state = self.initialize()
        client_order_id = execution.plan.client_order_id
        if (
            state.mode is not AgentMode.RUNNING
            or state.execution_epoch != expected_epoch
            or not state.is_reconciled
        ):
            raise RuntimeError("agent is not authorized for new exposure")
        existing = self._orders.get(client_order_id)
        if existing is not None:
            if (
                existing.status in {OrderExecutionStatus.PREPARED, OrderExecutionStatus.UNKNOWN}
                and client_order_id not in state.active_order_ids
            ):
                raise RuntimeError("agent is not authorized for order recovery")
            return False
        if len(state.active_order_ids) >= max_active_orders:
            raise RuntimeError("agent is not authorized for new exposure")
        self._state = state.model_copy(
            update={
                "active_order_ids": (*state.active_order_ids, client_order_id),
                "version": state.version + 1,
                "updated_at": datetime.now(UTC),
            }
        )
        self._orders[client_order_id] = execution
        return True

def get_order(self, client_order_id: str) -> OrderExecution | None:
    with self._lock:
        return self._orders.get(client_order_id)

def clear_active_order(self, client_order_id: str) -> AgentState:
    with self._lock:
        state = self.initialize()
        if client_order_id not in state.active_order_ids:
            raise RuntimeError("active order changed concurrently")
        self._state = state.model_copy(
            update={
                "active_order_ids": tuple(
                    tracked
                    for tracked in state.active_order_ids
                    if tracked != client_order_id
                ),
                "version": state.version + 1,
                "updated_at": datetime.now(UTC),
            }
        )
        return self._state

